insert into public.question_bank (teks_code, teks_item_id, subject, grade_num, course, difficulty, qtype, prompt, choices, answer_idx, explanation, source, status, gen_batch)
select distinct on (v.prompt) v.code, i.id, d.subject,
       case when i.grade_level = 'K' then 0 when i.grade_level ~ '^[0-9]+' then substring(i.grade_level from '^[0-9]+')::smallint end,
       case when i.grade_level is null then i.grade_course_title end,
       v.diff, 'mc', v.prompt, v.choices, v.ans, v.expl, v.src, 'checked', 'sla_1_v1'
from (values
('128.2.b.1.A',1,'When your teacher is giving a lesson, a good listener should:','["look at the speaker and wait to ask questions", "play with toys", "walk around the room", "turn away and talk"]'::jsonb,0,'Active listening means paying attention and asking questions.','original'),
('128.2.b.1.A',2,'A kindergarten student wants to understand a story better. What should the student do?','["say nothing at all", "ask a question about the part that is unclear", "cover both ears", "leave the story circle"]'::jsonb,1,'Asking questions helps you understand information.','original'),
('128.2.b.1.B',1,'The teacher says, Put away the blocks, then sit on the rug. What do you do first?','["wash your hands", "line up at the door", "tidy up the blocks", "sit on the rug"]'::jsonb,2,'Follow oral directions in the order they are given.','original'),
('128.2.b.1.B',2,'Restating a direction means:','["drawing it only", "erasing it", "ignoring it", "saying it again in your own words"]'::jsonb,3,'Restating shows you understood the direction.','original'),
('128.2.b.1.C',1,'Speaking audibly and clearly means that others can:','["hear and understand you", "see you wave", "smell your lunch", "feel your shoes"]'::jsonb,0,'Clear speech is loud enough and easy to understand.','original'),
('128.2.b.1.C',2,'Which is the best way to share an idea with the class?','["whisper to the floor", "stand up and speak in a clear voice", "hide behind a book", "shout across the room"]'::jsonb,1,'Share ideas in a voice that others can hear.','original'),
('128.2.b.1.D',1,'In a class discussion, a good rule is to:','["grab the speaker''s paper", "walk away", "wait for your turn to talk", "talk while others talk"]'::jsonb,2,'Taking turns is an agreed-upon discussion rule.','original'),
('128.2.b.1.D',2,'When a group works together on a poster, each student should:','["refuse to help", "ignore the plan", "do everything alone", "share the work and listen to the others"]'::jsonb,3,'Collaboration means working with others by the rules.','original'),
('128.2.b.1.E',1,'Which is a polite way to start a conversation with a new classmate?','["say hello and tell your name", "stare in silence", "take their pencil", "turn your back"]'::jsonb,0,'Introductions and greetings build social communication.','original'),
('128.2.b.1.E',1,'When a visitor enters the room in the morning, a student can say:','["Hasta luego", "Buenos días", "Buenas noches", "Hasta mañana"]'::jsonb,1,'Buenos días is a morning greeting.','original'),
('128.2.b.10.A',1,'Before writing a story, a student can plan by:','["closing the notebook", "writing the last word first", "drawing pictures and sharing ideas", "throwing away the paper"]'::jsonb,2,'Planning can start with talk and drawings.','original'),
('128.2.b.10.A',2,'Planning a piece of writing means:','["writing the title only", "erasing the page", "copying a classmate", "getting ideas ready before you write"]'::jsonb,3,'Planning generates ideas for writing.','original'),
('128.2.b.10.B',2,'A draft is a first try at writing that you:','["can later change and make better", "must never change", "cannot show anyone", "can only read aloud"]'::jsonb,0,'Drafts organize ideas and can be revised.','original'),
('128.2.b.10.B',2,'A kindergartner can make a draft by:','["tearing the paper", "drawing a picture or writing words about an idea", "leaving the page blank", "only coloring the border"]'::jsonb,1,'Drafts may be oral, pictorial or written.','original'),
('128.2.b.10.C',2,'To revise a drawing for your story, you might:','["hide it", "throw it away", "add more details to the picture", "cut it in half"]'::jsonb,2,'Revising adds details in pictures or words.','original'),
('128.2.b.10.C',2,'Revising means:','["finishing and never looking again", "copying the title", "turning the page upside down", "making your work better by adding details"]'::jsonb,3,'Revising improves a draft.','original'),
('128.2.b.10.D.i',2,'A complete sentence always tells:','["who or what and what happens", "only a color", "only a number", "only a place"]'::jsonb,0,'A sentence has a subject and an action.','original'),
('128.2.b.10.D.ii',3,'Ser and estar both mean to be. Which sentence uses estar to tell where something is?','["Yo soy alto.", "La mesa está en la sala.", "Ella es mi amiga.", "La mesa es grande."]'::jsonb,1,'Estar tells location or a changing condition.','original'),
('128.2.b.10.D.ii',3,'Which sentence uses ser to tell what someone is like?','["Mi hermana está triste.", "Mi hermana está aquí.", "Mi hermana es alta.", "Mi hermana está en casa."]'::jsonb,2,'Ser tells identity and lasting traits.','original'),
('128.2.b.10.D.iii',2,'Which article goes with the feminine word casa?','["los", "un", "el", "la"]'::jsonb,3,'Casa is feminine, so it uses la.','original'),
('128.2.b.10.D.iii',2,'What is the plural of the word libro?','["libros", "libras", "libra", "libre"]'::jsonb,0,'Add s to a noun that ends in a vowel.','original'),
('128.2.b.10.D.iv',2,'Which phrase has an article and an adjective that agree?','["el casa roja", "la casa roja", "la casa rojo", "los casa rojas"]'::jsonb,1,'Articles and adjectives agree with the noun.','original'),
('128.2.b.10.D.iv',2,'An adjective is a word that:','["joins two sentences", "names an action", "describes a noun", "ends a question"]'::jsonb,2,'Adjectives tell more about nouns.','original'),
('128.2.b.10.D.ix',2,'In Spanish, the letter h at the start of a word is usually:','["a z sound", "an s sound", "a loud k sound", "silent"]'::jsonb,3,'Silent h is a spelling pattern in Spanish.','original'),
('128.2.b.10.D.v',2,'Which word is a preposition that tells where?','["sobre", "azul", "rápido", "comer"]'::jsonb,0,'Prepositions show position or relationship.','original'),
('128.2.b.10.D.v',2,'In the sentence El libro está en la mesa, the word en tells:','["who is reading", "where the book is", "how many books", "what color"]'::jsonb,1,'En is a preposition showing place.','original'),
('128.2.b.10.D.vi',3,'Which pronoun is formal, used to address an adult politely?','["nosotros", "yo", "usted", "tú"]'::jsonb,2,'Usted is the formal you.','original'),
('128.2.b.10.D.vi',3,'A kindergartner speaks to a friend. The informal pronoun is:','["usted", "ustedes", "ellas", "tú"]'::jsonb,3,'Tú is the informal you for a friend.','original'),
('128.2.b.10.D.vii',1,'A sentence should begin with:','["a capital letter", "a period", "a question mark", "a small letter"]'::jsonb,0,'Capitalize the first letter of a sentence.','original'),
('128.2.b.10.D.vii',1,'The name of a person begins with:','["a number", "a capital letter", "a period", "a small letter"]'::jsonb,1,'Names begin with a capital letter.','original'),
('128.2.b.10.D.viii',1,'A sentence that tells something ends with:','["a hyphen", "a colon", "a period", "a comma"]'::jsonb,2,'A declarative sentence ends with a period.','original'),
('128.2.b.10.D.viii',2,'Which sentence has the correct end mark?','["Mi gato duerme", "Mi gato duerme-", "Mi gato duerme,", "Mi gato duerme."]'::jsonb,3,'Telling sentences end with a period.','original'),
('128.2.b.10.E',1,'When you finish writing, you can:','["share your writing with others", "tear it up", "sit on it", "hide it forever"]'::jsonb,0,'Writers share their work.','original'),
('128.2.b.10.E',1,'Sharing your writing means:','["erasing it", "letting others read or hear it", "burying it", "forgetting it"]'::jsonb,1,'Sharing gives writing an audience.','original'),
('128.2.b.11.A',2,'A personal narrative is a story about:','["a made-up robot", "the weather report", "something that happened to you", "a list of numbers"]'::jsonb,2,'Personal narratives tell about your own experiences.','original'),
('128.2.b.11.A',2,'A kindergartner who cannot write yet can compose a story by:','["skipping it", "only counting", "keeping it secret", "telling it to an adult who writes it down"]'::jsonb,3,'Dictation is a way to compose.','original'),
('128.2.b.11.B',2,'An informational text tries to:','["teach facts about a topic", "tell a silly rhyme only", "make you laugh only", "hide the facts"]'::jsonb,0,'Informational texts give facts.','original'),
('128.2.b.11.B',2,'Which sentence could be in an informational text?','["¡Qué sueño tan raro!", "Los pájaros tienen plumas.", "Mi sombrero habló.", "Había una vez un dragón."]'::jsonb,1,'Informational writing gives true facts.','original'),
('128.2.b.12.A',2,'A question you ask to learn about frogs is part of:','["a cartoon", "a spelling test", "an inquiry", "a lunch order"]'::jsonb,2,'Inquiry starts with questions.','original'),
('128.2.b.12.A',2,'With an adult, which is a good question to research?','["Frog.", "Green.", "Tadpoles.", "What do tadpoles eat?"]'::jsonb,3,'Good research questions ask about a topic.','original'),
('128.2.b.12.B',2,'A research plan tells:','["the steps you will take to find answers", "the answer only", "who won a game", "what to eat"]'::jsonb,0,'A plan lists how you will find information.','original'),
('128.2.b.12.B',3,'With help, a class makes a research plan before:','["packing up", "looking for information", "finishing the project", "reading the answer key"]'::jsonb,1,'Plan first, then research.','original'),
('128.2.b.12.C',2,'To find out about bees, you can gather information from:','["a broken toy", "a blank page", "books and videos with an adult", "a closed door"]'::jsonb,2,'Use a variety of sources.','original'),
('128.2.b.12.C',2,'A source is:','["a snack", "a game piece", "a type of crayon", "a place to get information"]'::jsonb,3,'Books and videos are sources.','original'),
('128.2.b.12.D',2,'After you gather facts about bees, you show you understand by:','["telling what you learned", "covering your eyes", "forgetting it", "skipping the facts"]'::jsonb,0,'Understanding means you can explain information.','original'),
('128.2.b.12.D',3,'Which shows understanding of what you read?','["closing the book", "saying a fact in your own words", "pointing at the cover only", "naming the font"]'::jsonb,1,'Restating shows understanding.','original'),
('128.2.b.12.E',2,'To share what you learned, you can present results by:','["hiding the paper", "leaving early", "speaking, writing or drawing", "staying silent"]'::jsonb,2,'Delivery may be written, oral or multimodal.','original'),
('128.2.b.12.E',3,'Presenting results in a multimodal way uses:','["only a blank page", "one word alone", "no audience", "words together with pictures or sound"]'::jsonb,3,'Multimodal means more than one mode.','original'),
('128.2.b.2.A.i',1,'Which two words rhyme?','["gato and pato", "sol and luna", "casa and perro", "gato and mesa"]'::jsonb,0,'Rhyming words end with the same sound.','original'),
('128.2.b.2.A.i',1,'Say a word that rhymes with mesa. A good choice is:','["rojo", "pesa", "libro", "sal"]'::jsonb,1,'Mesa and pesa end with the same sound.','original'),
('128.2.b.2.A.ii',1,'Which words start with the same sound?','["gato, mesa, pan", "sol, pie, ojo", "mono, mesa, mano", "luna, árbol, uva"]'::jsonb,2,'Alliteration means words begin with the same sound.','original'),
('128.2.b.2.A.ii',2,'Which set begins with the same simple syllable?','["sol, pan, agua", "perro, luna, casa", "tren, ojo, uva", "mapa, mano, mama"]'::jsonb,3,'They all begin with ma.','original'),
('128.2.b.2.A.iii',1,'How many words are in the spoken sentence Yo veo un gato?','["4", "3", "5", "2"]'::jsonb,0,'Count each word: yo, veo, un, gato.','original'),
('128.2.b.2.A.iii',1,'The sentence La niña canta has how many words?','["2", "3", "4", "1"]'::jsonb,1,'The words are la, niña, canta.','original'),
('128.2.b.2.A.iv',1,'How many syllables are in the word mesa?','["4", "3", "2", "1"]'::jsonb,2,'Me-sa has two syllables.','original')
) as v(code, diff, prompt, choices, ans, expl, src)
join public.teks_items i on i.code = v.code and i.is_standard
join public.teks_documents d on d.id = i.document_id and d.subject = 'Spanish Language Arts and English as a Second Language' and d.language = 'en'
on conflict (fingerprint) do nothing;
insert into public.question_bank (teks_code, teks_item_id, subject, grade_num, course, difficulty, qtype, prompt, choices, answer_idx, explanation, source, status, gen_batch)
select distinct on (v.prompt) v.code, i.id, d.subject,
       case when i.grade_level = 'K' then 0 when i.grade_level ~ '^[0-9]+' then substring(i.grade_level from '^[0-9]+')::smallint end,
       case when i.grade_level is null then i.grade_course_title end,
       v.diff, 'mc', v.prompt, v.choices, v.ans, v.expl, v.src, 'checked', 'sla_1_v1'
from (values
('128.2.b.2.A.iv',1,'How many syllables do you hear in the word mariposa?','["2", "3", "5", "4"]'::jsonb,3,'Ma-ri-po-sa has four syllables.','original'),
('128.2.b.2.A.ix',3,'Take the syllable ca out of casa. What is left?','["sa", "cas", "ca", "asa"]'::jsonb,0,'Deleting a syllable leaves the rest of the word.','original'),
('128.2.b.2.A.ix',3,'Change the first syllable of mesa to pe. What is the new word?','["sepa", "pesa", "meta", "mesa"]'::jsonb,1,'Replacing the first syllable creates a new word.','original'),
('128.2.b.2.A.v',2,'Blend the syllables ga and to. What word do you make?','["goto", "tago", "gato", "pato"]'::jsonb,2,'Blending joins syllables into a word.','original'),
('128.2.b.2.A.v',2,'Which word do you get by putting ma and no together?','["mana", "nomo", "mona", "mano"]'::jsonb,3,'Ma plus no makes mano.','original'),
('128.2.b.2.A.vi',2,'Say the word luna one syllable at a time. What are the parts?','["lu and na", "lu and nu", "lun and a", "l and una"]'::jsonb,0,'Luna splits into lu-na.','original'),
('128.2.b.2.A.vi',2,'Clap the syllables of pelota. How many claps?','["5", "3", "4", "2"]'::jsonb,1,'Pe-lo-ta has three syllables.','original'),
('128.2.b.2.A.vii',1,'What is the first sound in the word sol?','["o", "l", "s", "p"]'::jsonb,2,'The first sound in sol is s.','original'),
('128.2.b.2.A.vii',2,'What is the last sound in the word pan?','["a", "p", "m", "n"]'::jsonb,3,'Pan ends with the sound n.','original'),
('128.2.b.2.A.viii',2,'Blend the sounds m and a. What syllable do you make?','["ma", "mo", "am", "me"]'::jsonb,0,'M plus a blends to ma.','original'),
('128.2.b.2.A.viii',2,'Blend the sounds s and o. What syllable do you make?','["os", "so", "su", "sa"]'::jsonb,1,'S plus o blends to so.','original'),
('128.2.b.2.B.i',1,'Which letter makes the sound at the start of the word luna?','["m", "n", "l", "r"]'::jsonb,2,'The first letter of luna is l.','original'),
('128.2.b.2.B.i',1,'The letter m stands for the sound at the beginning of:','["gato", "pan", "sol", "mesa"]'::jsonb,3,'Mesa begins with m.','original'),
('128.2.b.2.B.ii',2,'Use letter sounds to read this word: sapo. What are its syllables?','["sa and po", "sa and sa", "sap and o", "s and apo"]'::jsonb,0,'Decode one syllable at a time.','original'),
('128.2.b.2.B.ii',3,'Which word is made from the syllables ca and ma?','["mama", "cama", "caca", "maca"]'::jsonb,1,'Ca plus ma reads cama.','original'),
('128.2.b.2.B.iii',3,'In the Spanish word hola, the letter h:','["sounds like z", "sounds like k", "makes no sound", "sounds like m"]'::jsonb,2,'H is silent in Spanish.','original'),
('128.2.b.2.B.iii',3,'Which word has the digraph ll?','["casa", "cara", "cama", "calle"]'::jsonb,3,'The letters ll form one digraph.','original'),
('128.2.b.2.B.iv',3,'If you change the last syllable of mesa from sa to ta, you get:','["meta", "mesa", "misa", "masa"]'::jsonb,0,'Changing a syllable makes a new word.','original'),
('128.2.b.2.B.iv',3,'Adding the syllable ca to the front of sa makes:','["cosa", "casa", "saca", "sasa"]'::jsonb,1,'Adding a syllable creates a new word.','original'),
('128.2.b.2.C.i',2,'Which letter should you use to spell the first sound in sapo?','["n", "t", "s", "p"]'::jsonb,2,'Spelling matches sounds to letters.','original'),
('128.2.b.2.C.i',2,'The sound you hear at the end of the word pan is spelled with:','["p", "m", "l", "n"]'::jsonb,3,'Pan ends with n.','original'),
('128.2.b.2.C.ii',3,'Which word follows the CV pattern for each of its two syllables?','["mesa", "tres", "sol", "mar"]'::jsonb,0,'Me and sa are each consonant plus vowel.','original'),
('128.2.b.2.C.ii',3,'The word sol follows which syllable pattern?','["CV", "CVC", "CCV", "VC"]'::jsonb,1,'Consonant, vowel, consonant.','original'),
('128.2.b.2.D.i',1,'Which part of a book has the title and picture on the outside?','["table of contents", "spine glue", "front cover", "last page"]'::jsonb,2,'The front cover shows the title.','original'),
('128.2.b.2.D.i',2,'The title page is found:','["at the very end", "on the back cover", "on the floor", "inside the book near the beginning"]'::jsonb,3,'The title page names the book inside.','original'),
('128.2.b.2.D.ii',1,'When you read a book, you hold it:','["right side up", "upside down", "sideways", "over your head"]'::jsonb,0,'Hold the book right side up.','original'),
('128.2.b.2.D.ii',1,'In Spanish and English books, reading moves:','["right to left", "from left to right and top to bottom", "around in circles", "bottom to top"]'::jsonb,1,'Text is read left to right, top to bottom.','original'),
('128.2.b.2.D.iii',2,'In the sentence Yo amo mi casa, how many spaces are between words?','["2", "1", "3", "4"]'::jsonb,2,'Four words have three spaces between them.','original'),
('128.2.b.2.D.iv',2,'A single letter and a printed word are different because a word:','["has no sound", "is a number", "is always one letter", "is made of letters together"]'::jsonb,3,'A word is a group of letters.','original'),
('128.2.b.2.D.iv',2,'Which of these is a letter, not a word?','["m", "pan", "sol", "mesa"]'::jsonb,0,'One mark is a letter.','original'),
('128.2.b.2.D.v',1,'Which letter is the uppercase form of the letter a?','["U", "A", "E", "O"]'::jsonb,1,'Uppercase A matches lowercase a.','original'),
('128.2.b.2.D.v',1,'The lowercase partner of the letter M is:','["w", "h", "m", "n"]'::jsonb,2,'Uppercase M goes with lowercase m.','original'),
('128.2.b.2.E',2,'When you write a letter, you should form it:','["without lifting any crayon", "as a scribble", "with random strokes", "starting at the right place and moving in the right direction"]'::jsonb,3,'Handwriting uses correct strokes and direction.','original'),
('128.2.b.2.E',2,'A good handwriting habit for kindergartners is to:','["write letters on the line", "draw only circles", "press until the paper tears", "write far above the page"]'::jsonb,0,'Letters sit on the baseline.','original'),
('128.2.b.3.A',2,'A picture dictionary helps you to:','["count to ten", "find a word and see its picture", "play a game", "write a song"]'::jsonb,1,'A picture dictionary shows words with pictures.','original'),
('128.2.b.3.A',2,'To find a word you do not know, you can look in:','["a coat pocket", "a toy chest", "a picture dictionary", "a lunch box"]'::jsonb,2,'Dictionaries help find words.','original'),
('128.2.b.3.B',2,'A picture in a story can help you learn:','["who won a game", "what time it is", "how to count money", "what a new word means"]'::jsonb,3,'Illustrations help clarify word meanings.','original'),
('128.2.b.3.B',3,'When you hear an unfamiliar word in a read-aloud, you can:','["look at the pictures for a clue", "stop listening", "change books", "close your eyes"]'::jsonb,0,'Use illustrations to learn word meanings.','original'),
('128.2.b.3.C',2,'Which word is an action word?','["arriba", "correr", "uno", "rojo"]'::jsonb,1,'Action words tell what someone does.','original'),
('128.2.b.3.C',2,'Which word names a position?','["saltar", "azul", "debajo", "dos"]'::jsonb,2,'Position words tell where something is.','original'),
('128.2.b.4',2,'Listening, speaking, reading and writing are all:','["unrelated to learning", "only for teachers", "games without rules", "language skills that help each other grow"]'::jsonb,3,'Foundational language skills are developed together.','original'),
('128.2.b.4',2,'When students listen to a story and then talk about it, they are using:','["listening and speaking together", "only handwriting", "only math", "no skills"]'::jsonb,0,'Language skills work together.','original'),
('128.2.b.5.A',2,'Why do we read a story?','["to waste time", "to enjoy it or to learn something", "to forget words", "to get tired"]'::jsonb,1,'Readers have a purpose for reading.','original'),
('128.2.b.5.A',2,'Before you read a book, you can set a purpose by asking:','["What is for lunch?", "Where is my coat?", "What do I want to learn?", "Who is at the door?"]'::jsonb,2,'A purpose guides reading.','original'),
('128.2.b.5.B',2,'Asking questions before, during and after reading helps you:','["read less", "skip pages", "forget the story", "understand the text more deeply"]'::jsonb,3,'Questions build understanding.','original'),
('128.2.b.5.B',2,'Which is a good question to ask during reading?','["Why did the character do that?", "What day is it?", "Is it recess?", "Where are the crayons?"]'::jsonb,0,'Questions about the text help understanding.','original'),
('128.2.b.5.C',2,'Looking at the cover and guessing what will happen is called:','["spelling", "making a prediction", "reading the end", "copying"]'::jsonb,1,'Predictions use text features.','original'),
('128.2.b.5.C',3,'After you read, you confirm a prediction by checking:','["the weather", "what you ate", "whether it came true", "the clock"]'::jsonb,2,'Confirm predictions against the text.','original'),
('128.2.b.5.D',2,'Creating a picture in your mind while a story is read is called:','["copying", "blinking", "clapping", "making a mental image"]'::jsonb,3,'Mental images deepen understanding.','original'),
('128.2.b.5.D',2,'If a story says the sun is bright over a green hill, you can picture:','["a sunny hill", "a crowded city", "a dark cave", "a snowy night"]'::jsonb,0,'Words help the reader visualize.','original'),
('128.2.b.5.E',2,'Saying This story reminds me of my dog is making:','["a prediction only", "a connection", "a mistake", "a rhyme"]'::jsonb,1,'Connections link text to experience.','original'),
('128.2.b.5.E',3,'A story about a birthday makes you think of your own party. This is a:','["rhyme", "map", "personal connection", "new word"]'::jsonb,2,'Personal connections tie text to your life.','original'),
('128.2.b.5.F',3,'An inference is when you:','["copy a word", "read the title", "say the page number", "use clues to figure out something not said"]'::jsonb,3,'Inferences use evidence.','original'),
('128.2.b.5.F',3,'A girl wears a coat and mittens. What can you infer?','["it is cold", "it is night", "it is hot", "it is lunch"]'::jsonb,0,'Clues in the text support inferences.','original'),
('128.2.b.5.G',3,'Deciding which details are most important in a story means you:','["erase the words", "evaluate the details", "skip the book", "count the pages"]'::jsonb,1,'Evaluating details finds what matters most.','original')
) as v(code, diff, prompt, choices, ans, expl, src)
join public.teks_items i on i.code = v.code and i.is_standard
join public.teks_documents d on d.id = i.document_id and d.subject = 'Spanish Language Arts and English as a Second Language' and d.language = 'en'
on conflict (fingerprint) do nothing;
insert into public.question_bank (teks_code, teks_item_id, subject, grade_num, course, difficulty, qtype, prompt, choices, answer_idx, explanation, source, status, gen_batch)
select distinct on (v.prompt) v.code, i.id, d.subject,
       case when i.grade_level = 'K' then 0 when i.grade_level ~ '^[0-9]+' then substring(i.grade_level from '^[0-9]+')::smallint end,
       case when i.grade_level is null then i.grade_course_title end,
       v.diff, 'mc', v.prompt, v.choices, v.ans, v.expl, v.src, 'checked', 'sla_1_v1'
from (values
('128.2.b.5.G',3,'Which detail is most important in a story about a lost puppy?','["the clock is round", "the door is open", "the puppy is lost", "the rug is blue"]'::jsonb,2,'The main problem is the key detail.','original'),
('128.2.b.5.H',3,'Putting together ideas from a text to make a new understanding is:','["rhyming", "printing", "tracing", "synthesizing"]'::jsonb,3,'Synthesis creates new understanding.','original'),
('128.2.b.5.H',3,'After reading two books about frogs, you combine what you learned. This is called:','["synthesis", "rhyming", "tracing", "spelling"]'::jsonb,0,'Synthesis combines information.','original'),
('128.2.b.5.I',2,'If a sentence does not make sense, you can fix your understanding by:','["skipping it forever", "reading it again", "guessing wildly", "throwing the book"]'::jsonb,1,'Re-reading is a comprehension strategy.','original'),
('128.2.b.5.I',3,'Monitoring comprehension means:','["counting words", "closing the book", "checking whether you understand as you read", "coloring pages"]'::jsonb,2,'Readers check and adjust their understanding.','original'),
('128.2.b.6.A',2,'A personal connection to a text is when you:','["read the title", "count pages", "guess the author", "tell how it relates to your own life"]'::jsonb,3,'Personal connections are a response to text.','original'),
('128.2.b.6.A',2,'After a story about friends, you say I have a friend like that. This is a:','["personal response", "title", "map", "rhyme"]'::jsonb,0,'Describing personal connections is a response.','original'),
('128.2.b.6.B',2,'After reading, you can respond by:','["leaving", "drawing, talking or writing", "sleeping", "hiding the book"]'::jsonb,1,'Responses may be oral, pictorial or written.','original'),
('128.2.b.6.B',2,'One way to respond to a story is to:','["hide your name", "skip recess", "draw your favorite part", "rip a page"]'::jsonb,2,'A drawing is a pictorial response.','original'),
('128.2.b.6.C',3,'Text evidence is:','["a favorite color", "a guess from nowhere", "a picture of a pet", "something in the text that supports your answer"]'::jsonb,3,'Evidence comes from the text.','original'),
('128.2.b.6.C',3,'You say the boy was sad because he cried. The word cried is:','["text evidence", "a rhyme", "a page number", "a title"]'::jsonb,0,'Evidence supports the response.','original'),
('128.2.b.6.D',2,'To retell a story, you:','["invent a new ending", "tell what happened in order", "skip the beginning", "only name the title"]'::jsonb,1,'Retelling keeps the meaning.','original'),
('128.2.b.6.D',2,'A good retelling includes the beginning, the middle and:','["a song", "a recipe", "the end", "a quiz"]'::jsonb,2,'A retelling follows story order.','original'),
('128.2.b.6.E',2,'One meaningful way to interact with a book is to:','["sit on it", "ignore it", "tear it", "illustrate or write about it"]'::jsonb,3,'Illustrating and writing are responses.','original'),
('128.2.b.6.E',2,'After reading, you can show what you know by:','["drawing a picture of the story", "leaving the room", "covering your eyes", "saying nothing ever"]'::jsonb,0,'Interacting with sources shows understanding.','original'),
('128.2.b.6.F',3,'Using a new word you just learned when you talk about a book shows:','["you are quiet", "you can respond with new vocabulary", "you stopped listening", "you forgot the word"]'::jsonb,1,'Use newly acquired vocabulary in responses.','original'),
('128.2.b.6.F',3,'The teacher teaches the word brillante. A student says, El sol es brillante. This shows:','["a rhyme", "a title", "using a new word", "a page number"]'::jsonb,2,'Using new vocabulary in response.','original'),
('128.2.b.7.A',3,'The theme of a story is:','["the last page", "the first word", "the cover color", "the big idea the story is about"]'::jsonb,3,'Theme is the basic idea or message.','original'),
('128.2.b.7.A',3,'A story shows friends sharing and helping. A possible theme is:','["friendship", "winter weather", "cooking", "speed"]'::jsonb,0,'Text evidence points to the theme.','original'),
('128.2.b.7.B',1,'The main character is:','["the setting", "the most important character in the story", "the author", "the title"]'::jsonb,1,'The main character is who the story is about.','original'),
('128.2.b.7.B',1,'A story is mostly about a boy who plants a garden. The main character is:','["the garden soil", "the page", "the person the story follows", "the title"]'::jsonb,2,'The main character is who the story is mostly about.','original'),
('128.2.b.7.C',2,'The problem in a story is the:','["setting", "title", "first page", "trouble the characters must solve"]'::jsonb,3,'Plot includes problem and resolution.','original'),
