('128.2.b.9.E',3,'A story told by someone who says I is in:','["second person", "third person", "fourth person", "first person"]'::jsonb,3,'First-person text uses I.','original'),
('128.2.b.9.E',3,'A story told with the words he and she about other people is in:','["third person", "no person", "first person", "second person"]'::jsonb,0,'Third person tells about others.','original')
) as v(code, diff, prompt, choices, ans, expl, src)
join public.teks_items i on i.code = v.code and i.is_standard
join public.teks_documents d on d.id = i.document_id and d.subject = 'Spanish Language Arts and English as a Second Language' and d.language = 'en'
on conflict (fingerprint) do nothing;
